code.C:
#include <stdio.h>
#include <string.h>
int main() {
    int n; char s[1000];
    if (scanf("%d %s", &n, s) == 2) {
        int len = strlen(s);
        if (len == 0) return 0;
        n %= len;
        printf("%s", s + n);
        for (int i = 0; i < n; i++) putchar(s[i]);
        putchar('\n');
    }
    return 0;
}

code.C++:
#include <iostream>
#include <string>
using namespace std;
int main() {
    int n; string s;
    if (cin >> n >> s) {
        if (!s.empty()) {
            n %= s.length();
            cout << s.substr(n) + s.substr(0, n) << "\n";
        }
    }
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (sc.hasNext()) {
                String s = sc.next();
                n %= s.length();
                System.out.println(s.substring(n) + s.substring(0, n));
            }
        }
    }
}

