import sys
def main():
    lines = [l.strip() for l in sys.stdin.read().splitlines() if l.strip()]
    if len(lines) >= 2:
        n = int(lines[0])
        s = lines[1]
        n %= len(s)
        print(s[n:] + s[:n])
if __name__ == "__main__": main()

